<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;训练几步后 running_mean:&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, bn.running_mean)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 逐渐逼近 5</span></span>
