<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eval 单样本输出:&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, bn(one_sample))</span></span>
